{
  "technical_and_design_decisions": [
    "Adopt Spring Cloud Netflix Eureka Client for all service registration (s-c-s modules and xd-admin server) to align with Spring ecosystem standards and minimize custom code.",
    "Implement a common Admin Service Provider Interface (SPI) using Java's standard SPI mechanism to abstract admin operations across deployment environments, enabling loose coupling between controllers and deployment-specific admin logic.",
    "Use Micrometer as the metrics facade integrated with Spring Boot Actuator for direct module metrics collection, leveraging existing Spring ecosystem tooling to avoid custom metrics implementation.",
    "Use Redis as the default metrics persistence backend as specified in U7, and configure Spring Boot Actuator's built-in metrics export functionality for 5-second default snapshot intervals.",
    "Use GitHub Actions as the CI/CD platform for both s-c-s build pipelines and module-launcher Docker image workflows, consistent with open source Spring project conventions.",
    "Port existing Spring XD FTP modules by adapting their core logic to the Spring Cloud Stream functional programming model, reusing existing FTP adapter code where possible to reduce rework and maintain feature parity.",
    "Expose collected module metrics via custom Spring Boot Actuator REST endpoints to provide a standardized, versioned API for metrics access without relying on xd-container coupling."
  ],
  "assumptions": [
    "Existing Spring XD controller codebase (ContainersController, StreamsController, ModulesController, JobsController) and FTP module source code are available for refactoring and porting, respectively.",
    "A running Eureka server instance is already provisioned and accessible for development, testing, and production use, with no need to implement or host Eureka server as part of this increment.",
    "A Redis instance is available for metrics persistence testing and production use, with necessary network access and credentials pre-configured.",
    "The project uses Maven as the build tool, consistent with standard Spring Framework and Spring Cloud project conventions.",
    "Access to the springcloud organization's DockerHub repository is already granted, with necessary permissions to push the module-launcher image.",
    "All required Spring dependencies (Spring Cloud Stream, Spring Cloud Eureka, Spring Boot Actuator, Micrometer, Spring Integration FTP) are compatible with Spring Framework 6.0 and Java 17+.",
    "Test environments (local development, CI runners) are pre-configured with required tools: Java 17, Maven, Docker, Redis client, and Eureka server access.",
    "The existing xd-container metrics coupling is well-documented, allowing for direct replacement with Actuator-based metrics collection without major architectural changes to the module runtime."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Design Eureka Registration for s-c-s Modules",
      "activity_description": "Design Eureka client configuration for Spring Cloud Stream modules, including instance metadata schema to expose current module state, and define registration lifecycle (startup registration, shutdown deregistration, state update on change).",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Implement Eureka Registration for s-c-s Modules",
      "activity_description": "Implement Eureka client integration in s-c-s modules, add logic to update instance metadata with current module state, and handle registration/deregistration lifecycle events.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Design Admin SPI Interface",
      "activity_description": "Design the common Admin Service Provider Interface (SPI) that abstracts admin operations (e.g., module deployment, stream management) across deployment environments, define method contracts for all operations required by existing controllers.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Implement Admin SPI and Default Local Implementation",
      "activity_description": "Implement the core Admin SPI interface, and a default implementation for local/standalone deployments that preserves existing controller behavior to ensure backward compatibility.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Refactor ContainersController to Use Admin SPI",
      "activity_description": "Refactor the existing ContainersController to delegate all admin operations to the Admin SPI instead of direct xd-container calls, update request handling and response mapping logic to align with SPI method signatures.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Refactor StreamsController to Use Admin SPI",
      "activity_description": "Refactor the existing StreamsController to use Admin SPI for all stream-related admin operations, remove direct xd-container dependencies, and validate existing stream management functionality.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Refactor ModulesController to Use Admin SPI",
      "activity_description": "Refactor the existing ModulesController to use Admin SPI for all module-related admin operations, eliminate direct xd-container coupling, and validate module management functionality.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Refactor JobsController to Use Admin SPI",
      "activity_description": "Refactor the existing JobsController to use Admin SPI for all job-related admin operations, remove direct xd-container dependencies, and validate job management functionality.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Design Direct Module Metrics Collection",
      "activity_description": "Design the approach to collect module (cf apps) metrics directly via Spring Boot Actuator and Micrometer, define the set of metrics to capture, and design the persistence and REST export mechanism.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Implement Direct Metrics Collection and REST Export",
      "activity_description": "Implement Micrometer metrics collection in s-c-s modules, add custom Spring Boot Actuator endpoints to expose collected metrics via standardized REST APIs, and remove all dependencies on xd-container for metrics relay.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Implement Metrics Persistence with Redis",
      "activity_description": "Implement Redis-backed metrics persistence using Spring Boot Actuator's built-in metrics export functionality, configure the default 5-second snapshot interval, and validate correct persistence and retrieval of metrics.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-12",
      "activity_name": "Design Eureka Registration for xd-admin Server",
      "activity_description": "Design Eureka client configuration for the xd-admin server, define service metadata to expose the admin endpoint as a discoverable service, and outline registration lifecycle handling for the admin server.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "ACT-13",
      "activity_name": "Implement Eureka Registration for xd-admin Server",
      "activity_description": "Implement Eureka client integration in the xd-admin server, add logic to register the admin endpoint with Eureka on startup, handle deregistration on shutdown, and validate discoverability of the admin service.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-14",
      "activity_name": "Setup CI Pipeline for s-c-s Builds",
      "activity_description": "Configure CI workflow to trigger on code commits, run unit and integration tests, build s-c-s artifacts, and publish build status and artifacts to the project artifact repository.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-15",
      "activity_name": "Port FTP Source Module from Spring XD to s-c-s",
      "activity_description": "Port the existing Spring XD FTP source module to the Spring Cloud Stream programming model, adapt the core FTP inbound channel adapter logic to function as a s-c-s source, and validate basic FTP file ingestion functionality.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-16",
      "activity_name": "Port FTP Sink Module from Spring XD to s-c-s",
      "activity_description": "Port the existing Spring XD FTP sink module to the Spring Cloud Stream programming model, adapt the core FTP outbound channel adapter logic to function as a s-c-s sink, and validate basic FTP file writing functionality.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-17",
      "activity_name": "Setup CI Workflow for Module-Launcher Docker Image",
      "activity_description": "Configure CI workflow to build the module-launcher Docker image on code changes, run image smoke tests, and push validated images to the springcloud DockerHub repository.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-18",
      "activity_name": "Integration Testing of All Increment Features",
      "activity_description": "Perform end-to-end integration testing across all implemented features to validate Eureka registration, SPI-based controller functionality, direct metrics collection/persistence/export, ported FTP modules, and CI workflows, resolve any identified defects.",
      "most_likely_effort": 3
    }
  ],
  "reported_total": {
    "most_likely_effort": 41
  }
}

